//go:build ignore

// Generates go_streams.txt with Go's compress/flate, compress/gzip and compress/zlib:
//
//	go run gen_go_streams.go > go_streams.txt
//
// Each line is "format name level length sha256(input) base64(compressed)". The inputs
// are generated here, so only their hash is stored.
//
// With -verify DIR it instead checks files written by the Rust tests
// (DL_FLATE_EXPORT=DIR cargo test -p dl-flate): every NAME.gz / NAME.zz / NAME.deflate
// must decompress with Go to the bytes of NAME.in.
package main

import (
	"bytes"
	"compress/flate"
	"compress/gzip"
	"compress/zlib"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"flag"
	"fmt"
	"io"
	"math/rand"
	"os"
	"path/filepath"
	"strings"
)

func inputs() map[string][]byte {
	r := rand.New(rand.NewSource(1951))
	random := make([]byte, 2048)
	r.Read(random)
	var js strings.Builder
	js.WriteString(`{"type":"result","id":"op-1","status":"applied","sets":[[`)
	for i := 0; i < 300; i++ {
		if i > 0 {
			js.WriteString(",")
		}
		fmt.Fprintf(&js, `{"FolioNum":"%d","Guest":"Nguyễn Văn %c","Amount":"%d.%02d","Room":%d,"Note":null}`,
			100000+r.Intn(900000), 'A'+rune(r.Intn(26)), r.Intn(10000000), r.Intn(100), 100+r.Intn(900))
	}
	js.WriteString(`]],"rowcounts":[300],"outputs":{"ReturnValue":0},"error":null}`)
	var text strings.Builder
	words := []string{"Khách", "sạn", "phòng", "hóa", "đơn", "thanh", "toán", "dịch", "vụ", "the", "and", "of"}
	for text.Len() < 20000 {
		text.WriteString(words[r.Intn(len(words))])
		text.WriteByte(" \n"[r.Intn(2)])
	}
	skewed := make([]byte, 20000)
	for i := range skewed {
		// Long codes: a geometric distribution over 200 symbols.
		s := 0
		for r.Intn(2) == 0 && s < 199 {
			s++
		}
		skewed[i] = byte(s)
	}
	return map[string][]byte{
		"empty":  {},
		"one":    []byte("a"),
		"run":    bytes.Repeat([]byte("a"), 1000),
		"random": random,
		"json":   []byte(js.String()),
		"text":   []byte(text.String()),
		"skewed": skewed,
	}
}

func main() {
	verify := flag.String("verify", "", "directory of Rust-compressed files to check")
	flag.Parse()
	if *verify != "" {
		os.Exit(check(*verify))
	}
	in := inputs()
	names := []string{"empty", "one", "run", "random", "json", "text", "skewed"}
	fmt.Println("# generated by gen_go_streams.go")
	for _, name := range names {
		data := in[name]
		sum := sha256.Sum256(data)
		for _, level := range []int{flate.NoCompression, flate.BestSpeed, flate.DefaultCompression, flate.BestCompression, flate.HuffmanOnly} {
			if level == flate.NoCompression && len(data) > 5000 {
				continue
			}
			var gz bytes.Buffer
			w, _ := gzip.NewWriterLevel(&gz, level)
			w.Write(data)
			w.Close()
			fmt.Printf("gzip %s %d %d %s %s\n", name, level, len(data), hex.EncodeToString(sum[:]), base64.StdEncoding.EncodeToString(gz.Bytes()))
		}
		var zz bytes.Buffer
		zw := zlib.NewWriter(&zz)
		zw.Write(data)
		zw.Close()
		fmt.Printf("zlib %s -1 %d %s %s\n", name, len(data), hex.EncodeToString(sum[:]), base64.StdEncoding.EncodeToString(zz.Bytes()))
		var raw bytes.Buffer
		fw, _ := flate.NewWriter(&raw, flate.DefaultCompression)
		fw.Write(data)
		fw.Close()
		fmt.Printf("deflate %s -1 %d %s %s\n", name, len(data), hex.EncodeToString(sum[:]), base64.StdEncoding.EncodeToString(raw.Bytes()))
	}
	// Two gzip members back to back decode as their concatenation.
	var multi bytes.Buffer
	for _, part := range []string{"first member, ", "second member"} {
		w := gzip.NewWriter(&multi)
		w.Write([]byte(part))
		w.Close()
	}
	both := []byte("first member, second member")
	sum := sha256.Sum256(both)
	fmt.Printf("gzip multi -1 %d %s %s\n", len(both), hex.EncodeToString(sum[:]), base64.StdEncoding.EncodeToString(multi.Bytes()))
}

func check(dir string) int {
	files, _ := filepath.Glob(filepath.Join(dir, "*.in"))
	bad, ok := 0, 0
	for _, f := range files {
		want, _ := os.ReadFile(f)
		base := strings.TrimSuffix(f, ".in")
		for _, ext := range []string{".gz", ".zz", ".deflate"} {
			comp, err := os.ReadFile(base + ext)
			if err != nil {
				continue
			}
			var rd io.Reader
			switch ext {
			case ".gz":
				rd, err = gzip.NewReader(bytes.NewReader(comp))
			case ".zz":
				rd, err = zlib.NewReader(bytes.NewReader(comp))
			default:
				rd = flate.NewReader(bytes.NewReader(comp))
			}
			if err == nil {
				var got []byte
				got, err = io.ReadAll(rd)
				if err == nil && !bytes.Equal(got, want) {
					err = fmt.Errorf("content differs (%d vs %d bytes)", len(got), len(want))
				}
			}
			if err != nil {
				fmt.Printf("FAIL %s%s: %v\n", base, ext, err)
				bad++
			} else {
				ok++
			}
		}
	}
	fmt.Printf("checked %d streams, %d failures\n", ok+bad, bad)
	if bad > 0 || ok == 0 {
		return 1
	}
	return 0
}
